import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"Install Jan","description":"Use the Jan desktop app to load local models and enable an API for MiniTavern over LAN.","frontmatter":{"title":"Install Jan","description":"Use the Jan desktop app to load local models and enable an API for MiniTavern over LAN.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Install Jan · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Use the Jan desktop app to load local models and enable an API for MiniTavern over LAN."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/jan/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/jan/install"}]]},"headers":[],"relativePath":"en/jan/install.md","filePath":"en/jan/install.md","lastUpdated":1787224147000}'),l={name:"en/jan/install.md"};function r(i,e,s,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="jan" tabindex="-1">Jan <a class="header-anchor" href="#jan" aria-label="Permalink to &quot;Jan&quot;">​</a></h1><p><a href="https://jan.ai/" target="_blank" rel="noreferrer">Jan</a> is a “local assistant” style desktop app: download/load models and enable an <strong>API Server</strong> (OpenAI-compatible) so MiniTavern can connect.</p><h2 id="steps-summary" tabindex="-1">Steps (summary) <a class="header-anchor" href="#steps-summary" aria-label="Permalink to &quot;Steps (summary)&quot;">​</a></h2><ol><li>Install and open Jan; download or import a model in-app.</li><li>Open <strong>Local API</strong> / <strong>API Server</strong> in settings (name follows the current version).</li><li>Allow LAN if there is a switch; note the <strong>port</strong>.</li><li>On the PC open <code>http://127.0.0.1:port/v1/models</code> and confirm the list.</li><li>On the phone use <code>http://YOUR_PC_IP:port/v1</code>; model name matches the list.</li></ol><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Jan iterates quickly — menu paths follow official docs.</li><li>If you cannot connect, confirm the server is Started, then firewall and IP (see <a href="/ultra_guides/en/troubleshoot">Troubleshoot</a>).</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="/ultra_guides/en/connect-app/minitavern">Configure in MiniTavern</a> · <a href="/ultra_guides/en/local/tools">Tools overview</a></p>',8)])])}const u=a(l,[["render",r]]);export{m as __pageData,u as default};
